/**
 * Excluded from the src/index.ts generated by ctix,
 * because this is an internal module imported only by sentry-client.ts.
 *
 * @ctix-exclude
 */
import fs from 'node:fs'
import path from 'node:path'

/**
 * Detects a release string of the form `<name>@<version>` from the consuming app's package.json
 * (read from the current working directory).
 *
 * Only the version is returned when the name is missing.
 * Returns undefined, without throwing, when package.json is missing, has no version, or cannot be parsed.
 *
 * @returns The detected release string, or undefined
 */
export function detectAppRelease(): string | undefined {
  const packageJsonPath = path.join(process.cwd(), 'package.json')
  if (!fs.existsSync(packageJsonPath)) {
    return undefined
  }
  try {
    const packageJson = JSON.parse(
      fs.readFileSync(packageJsonPath, 'utf8')
    ) as { name?: string; version?: string }
    if (!packageJson.version) {
      return undefined
    }
    return packageJson.name
      ? `${packageJson.name}@${packageJson.version}`
      : packageJson.version
  } catch {
    return undefined
  }
}
